package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"os"
	"time"

	"ai-challenge/day-16/internal/mcpdemo"
)

func main() {
	defaultEndpoint := os.Getenv("MCP_ENDPOINT")
	if defaultEndpoint == "" {
		defaultEndpoint = "http://127.0.0.1:8080/mcp"
	}
	endpoint := flag.String("endpoint", defaultEndpoint, "Streamable HTTP MCP endpoint")
	flag.Parse()

	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Second)
	defer cancel()

	result, err := mcpdemo.ConnectAndListTools(ctx, *endpoint)
	if err != nil {
		log.Fatal(err)
	}

	fmt.Println("MCP connection established")
	fmt.Printf("Server: %s %s\n", result.ServerName, result.ServerVersion)
	fmt.Printf("Protocol: %s\n", result.ProtocolVersion)
	fmt.Printf("Tools (%d):\n", len(result.Tools))
	for _, tool := range result.Tools {
		fmt.Printf("- %s: %s\n", tool.Name, tool.Description)
	}
}

package main

import (
	"context"
	"errors"
	"log"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"ai-challenge/day-16/internal/mcpdemo"
)

func main() {
	address := os.Getenv("MCP_ADDR")
	if address == "" {
		address = ":8080"
	}

	server := &http.Server{
		Addr:              address,
		Handler:           mcpdemo.Handler(),
		ReadHeaderTimeout: 5 * time.Second,
		ReadTimeout:       15 * time.Second,
		WriteTimeout:      30 * time.Second,
		IdleTimeout:       60 * time.Second,
	}

	ctx, stop := signal.NotifyContext(context.Background(), syscall.SIGINT, syscall.SIGTERM)
	defer stop()

	go func() {
		<-ctx.Done()
		shutdownCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
		defer cancel()
		if err := server.Shutdown(shutdownCtx); err != nil {
			log.Printf("graceful shutdown: %v", err)
		}
	}()

	log.Printf("%s %s listening on %s (MCP endpoint: /mcp)",
		mcpdemo.ServerName, mcpdemo.ServerVersion, address)
	if err := server.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
		log.Fatal(err)
	}
}

package mcpdemo

import (
	"context"
	"fmt"
	"net/http"
	"time"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

// ConnectionResult contains the negotiated server details and its complete tool list.
type ConnectionResult struct {
	ServerName      string
	ServerVersion   string
	ProtocolVersion string
	Tools           []*mcp.Tool
}

// ConnectAndListTools connects to endpoint and follows every tools/list page.
func ConnectAndListTools(ctx context.Context, endpoint string) (*ConnectionResult, error) {
	transport := &mcp.StreamableClientTransport{
		Endpoint: endpoint,
		HTTPClient: &http.Client{
			Timeout: 15 * time.Second,
		},
		DisableStandaloneSSE: true,
	}
	client := mcp.NewClient(
		&mcp.Implementation{Name: "day16-mcp-client", Version: ServerVersion},
		nil,
	)

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		return nil, fmt.Errorf("connect to MCP server: %w", err)
	}
	defer session.Close()

	result := &ConnectionResult{}
	if initialized := session.InitializeResult(); initialized != nil {
		result.ProtocolVersion = initialized.ProtocolVersion
		if initialized.ServerInfo != nil {
			result.ServerName = initialized.ServerInfo.Name
			result.ServerVersion = initialized.ServerInfo.Version
		}
	}

	params := &mcp.ListToolsParams{}
	for {
		page, err := session.ListTools(ctx, params)
		if err != nil {
			return nil, fmt.Errorf("list MCP tools: %w", err)
		}
		result.Tools = append(result.Tools, page.Tools...)
		if page.NextCursor == "" {
			break
		}
		params.Cursor = page.NextCursor
	}

	return result, nil
}

package mcpdemo

import (
	"context"
	"net/http"
	"net/http/httptest"
	"testing"
	"time"
)

func TestConnectAndListTools(t *testing.T) {
	httpServer := httptest.NewServer(Handler())
	t.Cleanup(httpServer.Close)

	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	result, err := ConnectAndListTools(ctx, httpServer.URL+"/mcp")
	if err != nil {
		t.Fatalf("ConnectAndListTools() error = %v", err)
	}
	if result.ServerName != ServerName {
		t.Fatalf("server name = %q, want %q", result.ServerName, ServerName)
	}
	if result.ProtocolVersion == "" {
		t.Fatal("protocol version is empty")
	}
	if len(result.Tools) != 1 {
		t.Fatalf("tool count = %d, want 1", len(result.Tools))
	}
	if result.Tools[0].Name != ToolName {
		t.Fatalf("tool name = %q, want %q", result.Tools[0].Name, ToolName)
	}
	if result.Tools[0].InputSchema == nil {
		t.Fatal("tool input schema is nil")
	}
}

func TestHealth(t *testing.T) {
	request := httptest.NewRequest(http.MethodGet, "/healthz", nil)
	response := httptest.NewRecorder()

	Handler().ServeHTTP(response, request)

	if response.Code != http.StatusOK {
		t.Fatalf("health status = %d, want %d", response.Code, http.StatusOK)
	}
}

package mcpdemo

import (
	"context"
	"encoding/json"
	"net/http"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

const (
	ServerName    = "day16-mcp-server"
	ServerVersion = "1.0.0"
	ToolName      = "server_status"
)

// StatusInput is intentionally empty: the status tool needs no arguments.
type StatusInput struct{}

// StatusOutput is the structured result returned by server_status.
type StatusOutput struct {
	Service string `json:"service" jsonschema:"MCP service name"`
	Status  string `json:"status" jsonschema:"Current service status"`
	Version string `json:"version" jsonschema:"MCP service version"`
}

// NewServer builds the MCP server and registers its tools.
func NewServer() *mcp.Server {
	server := mcp.NewServer(
		&mcp.Implementation{Name: ServerName, Version: ServerVersion},
		&mcp.ServerOptions{
			Instructions: "Use server_status to check that the demo MCP server is ready.",
		},
	)

	mcp.AddTool(server, &mcp.Tool{
		Name:        ToolName,
		Title:       "Server status",
		Description: "Returns the current status and version of the demo MCP server.",
	}, func(context.Context, *mcp.CallToolRequest, StatusInput) (*mcp.CallToolResult, StatusOutput, error) {
		return nil, StatusOutput{
			Service: ServerName,
			Status:  "ok",
			Version: ServerVersion,
		}, nil
	})

	return server
}

// Handler exposes both the MCP endpoint and a conventional container health check.
func Handler() http.Handler {
	mux := http.NewServeMux()
	server := NewServer()

	mux.Handle("/mcp", mcp.NewStreamableHTTPHandler(
		func(*http.Request) *mcp.Server { return server },
		&mcp.StreamableHTTPOptions{
			Stateless:                    true,
			JSONResponse:                 true,
			MaxRequestBodyBytes:          1 << 20,
			PropagateRequestCancellation: true,
		},
	))
	mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, _ *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(map[string]string{"status": "ok"})
	})

	return mux
}

package main

import (
	"bufio"
	"context"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"io"
	"log"
	"net/http"
	"os"
	"os/signal"
	"strings"
	"syscall"
	"time"

	"ai-challenge/day-17/internal/agent"
	"ai-challenge/day-17/internal/mcpgithub"
	appweb "ai-challenge/day-17/internal/web"
)

func main() {
	_ = loadEnv(".env")
	_ = loadEnv("../.env")
	serve := flag.Bool("serve", false, "start the web application")
	prompt := flag.String("prompt", "", "natural-language request")
	address := flag.String("addr", env("APP_ADDR", ":8080"), "web listen address")
	mcpEndpoint := flag.String("mcp-endpoint", env("MCP_ENDPOINT", "http://127.0.0.1:8081/mcp"), "MCP Streamable HTTP endpoint")
	model := flag.String("model", env("DEEPSEEK_MODEL", "deepseek-chat"), "DeepSeek model")
	baseURL := flag.String("base-url", env("DEEPSEEK_BASE_URL", "https://api.deepseek.com"), "DeepSeek API base URL")
	timeout := flag.Duration("timeout", 75*time.Second, "complete agent request timeout")
	traceJSON := flag.Bool("trace-json", false, "print the full response with MCP trace as JSON")
	flag.Parse()

	httpClient := &http.Client{Timeout: *timeout}
	chatAgent := agent.New(agent.Config{Model: *model, Timeout: *timeout, MaxTokens: 1200, Temperature: 0.2},
		agent.NewDeepSeekClient(os.Getenv("DEEPSEEK_API_KEY"), *baseURL, httpClient),
		mcpgithub.NewRemoteConnector(*mcpEndpoint, 20*time.Second),
	)
	if *serve {
		runServer(*address, chatAgent)
		return
	}
	value := strings.TrimSpace(*prompt)
	if value == "" {
		piped, _ := io.ReadAll(os.Stdin)
		value = strings.TrimSpace(string(piped))
	}
	if value == "" {
		log.Fatal("provide -prompt or pipe a request to stdin")
	}
	result, err := chatAgent.Ask(context.Background(), value)
	if err != nil {
		log.Fatal(err)
	}
	if *traceJSON {
		_ = json.NewEncoder(os.Stdout).Encode(result)
		return
	}
	for _, event := range result.Trace {
		encoded, _ := json.Marshal(event)
		fmt.Fprintln(os.Stderr, "TRACE", string(encoded))
	}
	fmt.Println(result.Content)
}

func runServer(address string, chatAgent *agent.Agent) {
	server := &http.Server{
		Addr: address, Handler: appweb.Handler(chatAgent), ReadHeaderTimeout: 5 * time.Second,
		ReadTimeout: 90 * time.Second, WriteTimeout: 90 * time.Second, IdleTimeout: 60 * time.Second,
	}
	ctx, stop := signal.NotifyContext(context.Background(), syscall.SIGINT, syscall.SIGTERM)
	defer stop()
	go func() {
		<-ctx.Done()
		shutdown, cancel := context.WithTimeout(context.Background(), 10*time.Second)
		defer cancel()
		_ = server.Shutdown(shutdown)
	}()
	log.Printf("day17 agent web app listening on %s", address)
	if err := server.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
		log.Fatal(err)
	}
}

func env(key, fallback string) string {
	if value := strings.TrimSpace(os.Getenv(key)); value != "" {
		return value
	}
	return fallback
}

func loadEnv(path string) error {
	file, err := os.Open(path)
	if errors.Is(err, os.ErrNotExist) {
		return nil
	}
	if err != nil {
		return err
	}
	defer file.Close()
	scanner := bufio.NewScanner(file)
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		key, value, ok := strings.Cut(line, "=")
		if !ok {
			continue
		}
		if _, exists := os.LookupEnv(strings.TrimSpace(key)); !exists {
			_ = os.Setenv(strings.TrimSpace(key), strings.Trim(strings.TrimSpace(value), `"'`))
		}
	}
	return scanner.Err()
}

