package agent

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"strings"
	"time"

	"ai-challenge/day-17/internal/mcpgithub"
)

const (
	defaultMaxToolRounds = 4
	defaultMaxToolCalls  = 8
)

type Config struct {
	Model         string
	System        string
	Timeout       time.Duration
	MaxTokens     int
	Temperature   float64
	MaxToolRounds int
	MaxToolCalls  int
}

type Agent struct {
	cfg       Config
	llm       LLM
	connector mcpgithub.Connector
}

func New(cfg Config, llm LLM, connector mcpgithub.Connector) *Agent {
	if cfg.Model == "" {
		cfg.Model = "deepseek-chat"
	}
	if cfg.System == "" {
		cfg.System = "You are a helpful assistant. Use available tools whenever fresh external data is needed. Base the final answer on tool results and never invent tool output."
	}
	if cfg.Timeout <= 0 {
		cfg.Timeout = 60 * time.Second
	}
	if cfg.MaxTokens <= 0 {
		cfg.MaxTokens = 1024
	}
	if cfg.MaxToolRounds <= 0 {
		cfg.MaxToolRounds = defaultMaxToolRounds
	}
	if cfg.MaxToolCalls <= 0 {
		cfg.MaxToolCalls = defaultMaxToolCalls
	}
	return &Agent{cfg: cfg, llm: llm, connector: connector}
}

func (a *Agent) Ask(ctx context.Context, prompt string) (Response, error) {
	prompt = strings.TrimSpace(prompt)
	if prompt == "" {
		return Response{}, errors.New("message cannot be empty")
	}
	if a.llm == nil || a.connector == nil {
		return Response{}, errors.New("agent dependencies are not configured")
	}
	ctx, cancel := context.WithTimeout(ctx, a.cfg.Timeout)
	defer cancel()

	session, err := a.connector.Connect(ctx)
	if err != nil {
		return Response{}, err
	}
	defer session.Close()
	mcpTools, err := session.ListTools(ctx)
	if err != nil {
		return Response{}, err
	}
	if len(mcpTools) == 0 {
		return Response{}, errors.New("MCP server returned no tools")
	}
	tools := make([]ToolDefinition, len(mcpTools))
	names := make([]string, len(mcpTools))
	for i, tool := range mcpTools {
		tools[i] = ToolDefinition{Type: "function", Function: FunctionDefinition{
			Name: tool.Name, Description: tool.Description, Parameters: tool.InputSchema,
		}}
		names[i] = tool.Name
	}
	trace := []TraceEvent{{Stage: "tools/list", Message: "MCP tools discovered: " + strings.Join(names, ", "), Result: mcpTools}}
	messages := []Message{{Role: "system", Content: a.cfg.System}, {Role: "user", Content: prompt}}
	totalCalls := 0

	for round := 0; round <= a.cfg.MaxToolRounds; round++ {
		request := ChatRequest{
			Model: a.cfg.Model, Messages: messages, Temperature: a.cfg.Temperature,
			MaxTokens: a.cfg.MaxTokens, Thinking: &ThinkingConfig{Type: "disabled"},
			Tools: tools, ToolChoice: "auto", Stream: false,
		}
		completion, err := a.llm.Complete(ctx, request)
		if err != nil {
			return Response{}, err
		}
		choice := completion.Choices[0]
		if len(choice.Message.ToolCalls) == 0 {
			content := strings.TrimSpace(choice.Message.Content)
			if content == "" {
				return Response{}, errors.New("model returned neither content nor tool calls")
			}
			trace = append(trace, TraceEvent{Stage: "final", Message: "Model produced the final answer from the conversation and tool results."})
			return Response{Content: content, Usage: completion.Usage, FinishReason: choice.FinishReason, Trace: trace}, nil
		}
		if round == a.cfg.MaxToolRounds {
			return Response{}, fmt.Errorf("tool round limit exceeded (%d)", a.cfg.MaxToolRounds)
		}
		choice.Message.Role = "assistant"
		messages = append(messages, choice.Message)
		for _, call := range choice.Message.ToolCalls {
			totalCalls++
			if totalCalls > a.cfg.MaxToolCalls {
				return Response{}, fmt.Errorf("tool call limit exceeded (%d)", a.cfg.MaxToolCalls)
			}
			arguments, err := decodeArguments(call.Function.Arguments)
			if err != nil {
				return Response{}, fmt.Errorf("decode arguments for %s: %w", call.Function.Name, err)
			}
			trace = append(trace, TraceEvent{Stage: "model/tool_call", Message: "The model selected an MCP tool.", Tool: call.Function.Name, Arguments: arguments})
			result, err := session.CallTool(ctx, call.Function.Name, arguments)
			if err != nil {
				return Response{}, err
			}
			content, publicResult, err := toolResultContent(result)
			if err != nil {
				return Response{}, err
			}
			stage := "mcp/tools/call"
			message := "MCP returned structured API data; it is now sent back to the model."
			if result.IsError {
				stage = "mcp/tool_error"
				message = "MCP returned a tool error; it is sent back to the model for correction."
			}
			trace = append(trace, TraceEvent{Stage: stage, Message: message, Tool: call.Function.Name, Result: publicResult})
			messages = append(messages, Message{Role: "tool", ToolCallID: call.ID, Content: content})
		}
	}
	return Response{}, errors.New("agent loop ended unexpectedly")
}

func decodeArguments(raw string) (map[string]any, error) {
	decoder := json.NewDecoder(strings.NewReader(raw))
	decoder.UseNumber()
	var arguments map[string]any
	if err := decoder.Decode(&arguments); err != nil {
		return nil, err
	}
	if arguments == nil {
		arguments = map[string]any{}
	}
	var extra any
	if err := decoder.Decode(&extra); !errors.Is(err, io.EOF) {
		if err == nil {
			return nil, errors.New("multiple JSON values")
		}
		return nil, err
	}
	return arguments, nil
}

func toolResultContent(result mcpgithub.ToolResult) (string, any, error) {
	if result.Structured != nil {
		encoded, err := json.Marshal(result.Structured)
		if err != nil {
			return "", nil, fmt.Errorf("encode structured MCP result: %w", err)
		}
		return string(encoded), result.Structured, nil
	}
	if result.Text == "" {
		return "", nil, errors.New("MCP tool returned an empty result")
	}
	var decoded any
	if json.Unmarshal([]byte(result.Text), &decoded) == nil {
		return result.Text,

if arguments == nil {
		arguments = map[string]any{}
	}
	var extra any
	if err := decoder.Decode(&extra); !errors.Is(err, io.EOF) {
		if err == nil {
			return nil, errors.New("multiple JSON values")
		}
		return nil, err
	}
	return arguments, nil
}

func toolResultContent(result mcpgithub.ToolResult) (string, any, error) {
	if result.Structured != nil {
		encoded, err := json.Marshal(result.Structured)
		if err != nil {
			return "", nil, fmt.Errorf("encode structured MCP result: %w", err)
		}
		return string(encoded), result.Structured, nil
	}
	if result.Text == "" {
		return "", nil, errors.New("MCP tool returned an empty result")
	}
	var decoded any
	if json.Unmarshal([]byte(result.Text), &decoded) == nil {
		return result.Text, decoded, nil
	}
	return result.Text, result.Text, nil
}

package agent

import (
	"context"
	"strings"
	"testing"

	"ai-challenge/day-17/internal/mcpgithub"
)

type fakeLLM struct {
	responses []ChatResponse
	requests  []ChatRequest
}

func (f *fakeLLM) Complete(_ context.Context, request ChatRequest) (ChatResponse, error) {
	f.requests = append(f.requests, request)
	response := f.responses[0]
	f.responses = f.responses[1:]
	return response, nil
}

type fakeConnector struct{ session *fakeSession }

func (f fakeConnector) Connect(context.Context) (mcpgithub.Session, error) { return f.session, nil }

type fakeSession struct {
	name      string
	arguments map[string]any
}

func (f *fakeSession) ListTools(context.Context) ([]mcpgithub.Tool, error) {
	return []mcpgithub.Tool{{
		Name: "get_github_repository", Description: "Get current public GitHub repository metadata.",
		InputSchema: map[string]any{"type": "object", "properties": map[string]any{
			"owner": map[string]any{"type": "string"}, "repository": map[string]any{"type": "string"},
		}, "required": []string{"owner", "repository"}, "additionalProperties": false},
	}}, nil
}

func (f *fakeSession) CallTool(_ context.Context, name string, arguments map[string]any) (mcpgithub.ToolResult, error) {
	f.name, f.arguments = name, arguments
	return mcpgithub.ToolResult{Structured: map[string]any{
		"full_name": "modelcontextprotocol/go-sdk", "language": "Go", "stars": 5153,
		"default_branch": "main", "rate_limit_remaining": 57, "source": "GitHub REST API",
	}}, nil
}

func (*fakeSession) Close() error { return nil }

func TestAgentToolCallLoopReturnsModelAnswerBasedOnMCPResult(t *testing.T) {
	llm := &fakeLLM{responses: []ChatResponse{
		{Choices: []Choice{{FinishReason: "tool_calls", Message: Message{ToolCalls: []ToolCall{{
			ID: "call-1", Type: "function", Function: ToolCallFunction{Name: "get_github_repository", Arguments: `{"owner":"modelcontextprotocol","repository":"go-sdk"}`},
		}}}}}},
		{Choices: []Choice{{FinishReason: "stop", Message: Message{Content: "modelcontextprotocol/go-sdk написан на Go и имеет 5153 звезды."}}}},
	}}
	session := &fakeSession{}
	chatAgent := New(Config{Model: "fake-model"}, llm, fakeConnector{session: session})

	result, err := chatAgent.Ask(context.Background(), "Расскажи об актуальном состоянии репозитория modelcontextprotocol/go-sdk")
	if err != nil {
		t.Fatalf("Ask() error = %v", err)
	}
	if session.name != "get_github_repository" || session.arguments["owner"] != "modelcontextprotocol" || session.arguments["repository"] != "go-sdk" {
		t.Fatalf("tool call = %q %#v", session.name, session.arguments)
	}
	if len(llm.requests) != 2 {
		t.Fatalf("LLM request count = %d", len(llm.requests))
	}
	second := llm.requests[1]
	toolMessage := second.Messages[len(second.Messages)-1]
	if len(second.Messages) < 4 || toolMessage.Role != "tool" || toolMessage.ToolCallID != "call-1" || !strings.Contains(toolMessage.Content, "5153") || !strings.Contains(toolMessage.Content, "GitHub REST API") {
		t.Fatalf("tool result was not sent to model: %+v", second.Messages)
	}
	if llm.requests[0].ToolChoice != "auto" || len(llm.requests[0].Tools) != 1 || llm.requests[0].Tools[0].Function.Name != "get_github_repository" {
		t.Fatalf("first model request does not contain MCP tool with auto choice: %+v", llm.requests[0])
	}
	if !strings.Contains(result.Content, "5153") {
		t.Fatalf("final answer does not use tool result: %q", result.Content)
	}
	if len(result.Trace) != 4 || result.Trace[1].Stage != "model/tool_call" || result.Trace[2].Stage != "mcp/tools/call" {
		t.Fatalf("unexpected trace: %+v", result.Trace)
	}
	if result.Trace[0].Result == nil {
		t.Fatal("tools/list trace does not include schemas")
	}
}

package agent

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"strings"
)

var ErrLLM = errors.New("LLM API error")

type DeepSeekClient struct {
	APIKey     string
	BaseURL    string
	HTTPClient *http.Client
}

func NewDeepSeekClient(apiKey, baseURL string, client *http.Client) *DeepSeekClient {
	if client == nil {
		client = http.DefaultClient
	}
	baseURL = strings.TrimRight(strings.TrimSpace(baseURL), "/")
	if baseURL == "" {
		baseURL = "https://api.deepseek.com"
	}
	return &DeepSeekClient{APIKey: strings.TrimSpace(apiKey), BaseURL: baseURL, HTTPClient: client}
}

func (c *DeepSeekClient) Complete(ctx context.Context, request ChatRequest) (ChatResponse, error) {
	if c.APIKey == "" {
		return ChatResponse{}, errors.New("DEEPSEEK_API_KEY is not configured")
	}
	payload, err := json.Marshal(request)
	if err != nil {
		return ChatResponse{}, fmt.Errorf("encode LLM request: %w", err)
	}
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, c.BaseURL+"/chat/completions", bytes.NewReader(payload))
	if err != nil {
		return ChatResponse{}, fmt.Errorf("create LLM request: %w", err)
	}
	req.Header.Set("Authorization", "Bearer "+c.APIKey)
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("Accept", "application/json")

	response, err := c.HTTPClient.Do(req)
	if err != nil {
		return ChatResponse{}, fmt.Errorf("%w: request failed: %v", ErrLLM, err)
	}
	defer response.Body.Close()
	body, err := io.ReadAll(io.LimitReader(response.Body, 4<<20))
	if err != nil {
		return ChatResponse{}, fmt.Errorf("%w: read response: %v", ErrLLM, err)
	}
	if response.StatusCode < http.StatusOK || response.StatusCode >= http.StatusMultipleChoices {
		return ChatResponse{}, fmt.Errorf("%w: HTTP %d: %s", ErrLLM, response.StatusCode, llmError(body))
	}
	var decoded ChatResponse
	if err := json.Unmarshal(body, &decoded); err != nil {
		return ChatResponse{}, fmt.Errorf("%w: decode response: %v", ErrLLM, err)
	}
	if len(decoded.Choices) == 0 {
		return ChatResponse{}, fmt.Errorf("%w: response has no choices", ErrLLM)
	}
	return decoded, nil
}

func llmError(body []byte) string {
	var envelope struct {
		Error any `json:"error"`
	}
	if json.Unmarshal(body, &envelope) == nil && envelope.Error != nil {
		if encoded, err := json.Marshal(envelope.Error); err == nil {
			return string(encoded)
		}
	}
	value := strings.TrimSpace(string(body))
	if value == "" {
		return "empty response body"
	}
	if len(value) > 500 {
		return value[:500] + "…"
	}
	return value
}

