		{"missing owner", RepositoryInput{Repository: "go-sdk"}, false},
		{"missing repository", RepositoryInput{Owner: "owner"}, false},
		{"owner starts with hyphen", RepositoryInput{Owner: "-owner", Repository: "go-sdk"}, false},
