// Package decimal implements the small, exact base-10 arithmetic surface the
// application needs. It deliberately avoids binary floating-point values.
package decimal

import (
	"errors"
	"fmt"
	"math/big"
	"regexp"
	"strings"
)

var pattern = regexp.MustCompile(`^([+-]?)([0-9]+)(?:\.([0-9]+))?(?:[eE]([+-]?[0-9]+))?$`)

// Decimal is an arbitrary-precision integer coefficient with a decimal scale.
type Decimal struct {
	coefficient *big.Int
	scale       int
}

func Parse(value string) (Decimal, error) {
	value = strings.TrimSpace(value)
	match := pattern.FindStringSubmatch(value)
	if match == nil {
		return Decimal{}, fmt.Errorf("invalid decimal %q", value)
	}
	digits := strings.TrimLeft(match[2]+match[3], "0")
	if digits == "" {
		digits = "0"
	}
	coefficient, ok := new(big.Int).SetString(digits, 10)
	if !ok {
		return Decimal{}, errors.New("invalid decimal coefficient")
	}
	if match[1] == "-" {
		coefficient.Neg(coefficient)
	}
	exponent := 0
	if match[4] != "" {
		if _, err := fmt.Sscanf(match[4], "%d", &exponent); err != nil {
			return Decimal{}, fmt.Errorf("invalid decimal exponent: %w", err)
		}
	}
	scale := len(match[3]) - exponent
	if scale < 0 {
		coefficient.Mul(coefficient, pow10(-scale))
		scale = 0
	}
	return normalize(Decimal{coefficient: coefficient, scale: scale}), nil
}

func MustParse(value string) Decimal {
	d, err := Parse(value)
	if err != nil {
		panic(err)
	}
	return d
}

func (d Decimal) String() string {
	d = d.valid()
	negative := d.coefficient.Sign() < 0
	digits := new(big.Int).Abs(d.coefficient).String()
	if d.scale > 0 {
		if len(digits) <= d.scale {
			digits = strings.Repeat("0", d.scale-len(digits)+1) + digits
		}
		index := len(digits) - d.scale
		digits = digits[:index] + "." + digits[index:]
	}
	if negative && digits != "0" {
		return "-" + digits
	}
	return digits
}

func (d Decimal) Sign() int { return d.valid().coefficient.Sign() }

func (d Decimal) Cmp(other Decimal) int {
	a, b := align(d.valid(), other.valid())
	return a.Cmp(b)
}

func (d Decimal) Sub(other Decimal) Decimal {
	a, b := align(d.valid(), other.valid())
	return normalize(Decimal{coefficient: new(big.Int).Sub(a, b), scale: max(d.scale, other.scale)})
}

func (d Decimal) Mul(other Decimal) Decimal {
	d, other = d.valid(), other.valid()
	return normalize(Decimal{coefficient: new(big.Int).Mul(d.coefficient, other.coefficient), scale: d.scale + other.scale})
}

// Div returns a value rounded half away from zero to precision fractional digits.
func (d Decimal) Div(other Decimal, precision int) (Decimal, error) {
	d, other = d.valid(), other.valid()
	if other.coefficient.Sign() == 0 {
		return Decimal{}, errors.New("division by zero")
	}
	if precision < 0 || precision > 100 {
		return Decimal{}, errors.New("precision must be between 0 and 100")
	}
	numerator := new(big.Int).Mul(d.coefficient, pow10(other.scale+precision))
	denominator := new(big.Int).Mul(other.coefficient, pow10(d.scale))
	quotient, remainder := new(big.Int).QuoRem(numerator, denominator, new(big.Int))
	if remainder.Sign() != 0 {
		doubleRemainder := new(big.Int).Abs(remainder)
		doubleRemainder.Mul(doubleRemainder, big.NewInt(2))
		if doubleRemainder.Cmp(new(big.Int).Abs(denominator)) >= 0 {
			if numerator.Sign()*denominator.Sign() < 0 {
				quotient.Sub(quotient, big.NewInt(1))
			} else {
				quotient.Add(quotient, big.NewInt(1))
			}
		}
	}
	return normalize(Decimal{coefficient: quotient, scale: precision}), nil
}

func PercentChange(first, last Decimal, precision int) (Decimal, error) {
	if first.Sign() == 0 {
		return Decimal{}, errors.New("cannot calculate percentage change from zero")
	}
	return last.Sub(first).Mul(MustParse("100")).Div(first, precision)
}

func align(a, b Decimal) (*big.Int, *big.Int) {
	scale := max(a.scale, b.scale)
	left := new(big.Int).Set(a.coefficient)
	right := new(big.Int).Set(b.coefficient)
	left.Mul(left, pow10(scale-a.scale))
	right.Mul(right, pow10(scale-b.scale))
	return left, right
}

func normalize(d Decimal) Decimal {
	if d.coefficient == nil {
		d.coefficient = new(big.Int)
	}
	ten := big.NewInt(10)
	zero := new(big.Int)
	for d.scale > 0 {
		q, r := new(big.Int).QuoRem(d.coefficient, ten, new(big.Int))
		if r.Cmp(zero) != 0 {
			break
		}
		d.coefficient = q
		d.scale--
	}
	return d
}

func (d Decimal) valid() Decimal {
	if d.coefficient == nil {
		return Decimal{coefficient: new(big.Int)}
	}
	return d
}

func pow10(n int) *big.Int { return new(big.Int).Exp(big.NewInt(10), big.NewInt(int64(n)), nil) }

package decimal

import "testing"

func TestExactDecimalArithmetic(t *testing.T) {
	for input, want := range map[string]string{
		"001.2300": "1.23", "1e-3": "0.001", "1.25E2": "125", "-0.000": "0",
	} {
		got, err := Parse(input)
		if err != nil || got.String() != want {
			t.Fatalf("Parse(%q) = %q, %v; want %q", input, got.String(), err, want)
		}
	}
	amount := MustParse("100")
	rate := MustParse("0.923456789123456789")
	if got := amount.Mul(rate).String(); got != "92.3456789123456789" {
		t.Fatalf("conversion = %s", got)
	}
	change, err := PercentChange(MustParse("0.8"), MustParse("1"), 12)
	if err != nil || change.String() != "25" {
		t.Fatalf("percentage = %s, %v", change.String(), err)
	}
}

package frankfurter

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"regexp"
	"strings"
	"time"

	"ai-challenge/day-18/internal/decimal"
)

const (
	DefaultBaseURL  = "https://api.frankfurter.dev"
	Source          = "Frankfurter API v2 — reference rates from central banks and official sources"
	UserAgent       = "day-18-currency/1.0 (+https://frankfurter.dev/)"
	defaultMaxBytes = int64(1 << 20)
)

var (
	ErrUnsupportedCurrency = errors.New("unsupported currency")
	ErrRateLimited         = errors.New("Frankfurter API rate limited")
	ErrUpstream            = errors.New("Frankfurter API unavailable")
	currencyPattern        = regexp.MustCompile(`^[A-Z]{3}$`)
)

type HTTPDoer interface {
	Do(*http.Request) (*http.Response, error)
}

type Client struct {
	HTTPClient       HTTPDoer
	BaseURL          string
	Timeout          time.Duration
	MaxResponseBytes int64
}

type Rate struct {
	Date    string    `json:"date"`
	Base    string    `json:"base"`
	Quote   string    `json:"quote"`
	Value   string    `json:"rate"`
	Source  string    `json:"source"`
	Fetched time.Time `json:"fetched_at"`
}

type Currency struct {
	ISOCode string `json:"iso_code"`
	Name    string `json:"name"`
}

type APIError struct {
	StatusCode int
	Message    string
	Kind       error
}

func (e *APIError) Error() string {
	return fmt.Sprintf("Frankfurter API HTTP %d: %s", e.StatusCode, e.Message)
}
func (e *APIError) Unwrap() error { return e.Kind }

func NewClient(httpClient HTTPDoer) *Client {
	if httpClient == nil {
		httpClient = &http.Client{Timeout: 12 * time.Second}
	}
	return &Client{HTTPClient: httpClient, BaseURL: DefaultBaseURL, Timeout: 12 * time.Second, MaxResponseBytes: defaultMaxBytes}
}

func NormalizeCurrency(value string) (string, error) {
	value = strings.ToUpper(strings.TrimSpace(value))
	if !currencyPattern.MatchString(value) {
		return "", errors.New("currency must be a three-letter ISO 4217 code")
	}
	return value, nil
}

func (c *Client) GetRate(ctx context.Context, base, quote string) (Rate, error) {
	base, err := NormalizeCurrency(base)
	if err != nil {
		return Rate{}, err
	}
	quote, err = NormalizeCurrency(quote)
	if err != nil {
		return Rate{}, err
	}
	endpoint, err := url.Parse(strings.TrimRight(c.BaseURL, "/") + "/v2/rate/" + url.PathEscape(base) + "/" + url.PathEscape(quote))
	if err != nil {
		return Rate{}, fmt.Errorf("build Frankfurter URL: %w", err)
	}
	body, err := c.get(ctx, endpoint.String())
	if err != nil {
		return Rate{}, err
	}
	var response struct {
		Date  string      `json:"date"`
		Base  string      `json:"base"`
		Quote string      `json:"quote"`
		Rate  json.Number `json:"rate"`
	}
	decoder := json.NewDecoder(strings.NewReader(string(body)))
	decoder.UseNumber()
	if err := decoder.Decode(&response); err != nil {
		return Rate{}, fmt.Errorf("decode Frankfurter rate: %w", err)
	}
	if response.Date == "" || response.Base != base || response.Quote != quote || response.Rate == "" {
		return Rate{}, errors.New("Frankfurter API returned an incomplete or mismatched rate")
	}
	if _, err := time.Parse("2006-01-02", response.Date); err != nil {
		return Rate{}, errors.New("Frankfurter API returned an invalid rate date")
	}
	parsed, err := decimal.Parse(response.Rate.String())
	if err != nil || parsed.Sign() <= 0 {
		return Rate{}, errors.New("Frankfurter API returned an invalid positive rate")
	}
	return Rate{Date: response.Date, Base: base, Quote: quote, Value: parsed.String(), Source: Source, Fetched: time.Now().UTC()}, nil
}

func (c *Client) ListCurrencies(ctx context.Context) ([]Currency, error) {
	body, err := c.get(ctx, strings.TrimRight(c.BaseURL, "/")+"/v2/currencies")
	if err != nil {
		return nil, err
	}
	var currencies []Currency
	if err := json.Unmarshal(body, &currencies); err != nil {
		return nil, fmt.Errorf("decode Frankfurter currencies: %w", err)
	}
	if len(currencies) == 0 {
		return nil, errors.New("Frankfurter API returned no currencies")
	}
	for _, item := range currencies {
		if _, err := NormalizeCurrency(item.ISOCode); err != nil || strings.TrimSpace(item.Name) == "" {
			return nil, errors.New("Frankfurter API returned an invalid currency catalogue")
		}
	}
	return currencies, nil
}

func (c *Client) ValidatePair(ctx context.Context, base, quote string) error {
	currencies, err := c.ListCurrencies(ctx)
	if err != nil {
		return err
	}
	foundBase, foundQuote := false, false
	for _, item := range currencies {
		foundBase = foundBase || item.ISOCode == base
		foundQuote = foundQuote || item.ISOCode == quote
	}
	if !foundBase || !foundQuote {
		missing := base
		if foundBase {
			missing = quote
		}
		return fmt.Errorf("%w: %s is not in the Frankfurter currency catalogue", ErrUnsupportedCurrency, missing)
	}
	return nil
}

