func TestMCPContractAllTools(t *testing.T) {
	wikiServer := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) { _, _ = w.Write([]byte(`{"query":{"pages":[]}}`)) }))
	defer wikiServer.Close()
	wiki := NewWikipediaClient(wikiServer.Client())
	wiki.BaseURL = wikiServer.URL
	connector := mcpclient.InMemoryConnector{Server: NewServer(wiki, NewSaver(t.TempDir()))}
	session, err := connector.Connect(context.Background())
	if err != nil {
		t.Fatal(err)
	}
	defer session.Close()
	tools, err := session.ListTools(context.Background())
	if err != nil {
		t.Fatal(err)
	}
	if len(tools) != 3 {
		t.Fatalf("got %d tools", len(tools))
	}
	want := map[string]bool{SearchToolName: false, SummarizeToolName: false, SaveToolName: false}
	for _, tool := range tools {
		want[tool.Name] = true
		input, ok := tool.InputSchema.(map[string]any)
		if !ok {
			t.Fatalf("%s input schema type %T", tool.Name, tool.InputSchema)
		}
		if input["additionalProperties"] != false {
			t.Errorf("%s input additionalProperties", tool.Name)
		}
		if _, exists := input["required"]; !exists || input["required"] == nil {
			t.Errorf("%s invalid required", tool.Name)
		}
		output, ok := tool.OutputSchema.(map[string]any)
		if !ok || output["additionalProperties"] != false {
			t.Errorf("%s output schema not strict", tool.Name)
		}
		if tool.Annotations == nil {
			t.Errorf("%s annotations missing", tool.Name)
		}
		annotations, ok := tool.Annotations.(*mcp.ToolAnnotations)
		if !ok {
			t.Fatalf("%s annotations type %T", tool.Name, tool.Annotations)
		}
		if annotations.OpenWorldHint == nil {
			t.Errorf("%s openWorldHint missing", tool.Name)
		} else if tool.Name == SearchToolName && !*annotations.OpenWorldHint {
			t.Error("search must be open-world")
		} else if tool.Name != SearchToolName && *annotations.OpenWorldHint {
			t.Errorf("%s must be closed-world", tool.Name)
		}
		if (tool.Name != SaveToolName) != annotations.ReadOnlyHint {
			t.Errorf("%s readOnlyHint=%v", tool.Name, annotations.ReadOnlyHint)
		}
		assertStrictObjects(t, tool.Name+" input", input)
		assertStrictObjects(t, tool.Name+" output", output)
	}
	for name, found := range want {
		if !found {
			t.Errorf("missing %s", name)
		}
	}
	search, err := session.CallTool(context.Background(), SearchToolName, map[string]any{"query": "x", "limit": 1})
	if err != nil || search.IsError {
		t.Fatalf("search call: %+v %v", search, err)
	}
	summary, err := session.CallTool(context.Background(), SummarizeToolName, map[string]any{"query": "x", "documents": []any{}, "max_sentences": 1})
	if err != nil || summary.IsError {
		t.Fatalf("summary call: %+v %v", summary, err)
	}
	saved, err := session.CallTool(context.Background(), SaveToolName, map[string]any{"filename": "x.md", "content": "summary", "sources": []any{}, "query": "x"})
	if err != nil || saved.IsError {
		t.Fatalf("save call: %+v %v", saved, err)
	}
}

func assertStrictObjects(t *testing.T, path string, schema any) {
	t.Helper()
	switch value := schema.(type) {
	case map[string]any:
		if value["type"] == "object" {
			if value["additionalProperties"] != false {
				t.Errorf("%s is not strict", path)
			}
			if required, exists := value["required"]; !exists || required == nil {
				t.Errorf("%s has missing/null required", path)
			}
		}
		for key, child := range value {
			assertStrictObjects(t, path+"/"+key, child)
		}
	case []any:
		for i, child := range value {
			assertStrictObjects(t, fmt.Sprintf("%s/%d", path, i), child)
		}
	}
}

package pipeline

import (
	"crypto/sha256"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"time"
)

var safeFilename = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9._-]{0,119}\.md$`)

type Saver struct {
	OutputDir string
	Now       func() time.Time
}

func NewSaver(outputDir string) *Saver { return &Saver{OutputDir: outputDir, Now: time.Now} }

func (s *Saver) Save(input SaveInput) (SaveOutput, error) {
	input.Filename = strings.TrimSpace(input.Filename)
	input.Query = cleanSpace(input.Query)
	input.Content = strings.TrimSpace(input.Content)
	if filepath.IsAbs(input.Filename) || strings.Contains(input.Filename, "..") || strings.ContainsAny(input.Filename, `/\\`) || !safeFilename.MatchString(input.Filename) {
		return SaveOutput{}, errors.New("filename must be a safe relative .md filename")
	}
	if input.Query == "" || len([]rune(input.Query)) > 300 {
		return SaveOutput{}, errors.New("query must contain 1 to 300 characters")
	}
	if input.Content == "" {
		return SaveOutput{}, errors.New("content cannot be empty")
	}
	if len([]byte(input.Content)) > MaxFileContent {
		return SaveOutput{}, fmt.Errorf("content exceeds %d bytes", MaxFileContent)
	}
	if len(input.Sources) > 5 {
		return SaveOutput{}, errors.New("sources must contain at most 5 items")
	}
	now := time.Now().UTC()
	if s.Now != nil {
		now = s.Now().UTC()
	}
	markdown := buildMarkdown(input, now)
	if err := os.MkdirAll(s.OutputDir, 0o750); err != nil {
		return SaveOutput{}, fmt.Errorf("create output directory: %w", err)
	}
	target := filepath.Join(s.OutputDir, input.Filename)
	cleanRoot, err := filepath.Abs(s.OutputDir)
	if err != nil {
		return SaveOutput{}, fmt.Errorf("resolve output directory: %w", err)
	}
	cleanTarget, err := filepath.Abs(target)
	if err != nil || filepath.Dir(cleanTarget) != cleanRoot {
		return SaveOutput{}, errors.New("resolved path is outside output directory")
	}
	temp, err := os.CreateTemp(cleanRoot, ".day19-*.tmp")
	if err != nil {
		return SaveOutput{}, fmt.Errorf("create temporary file: %w", err)
	}
	tempName := temp.Name()
	keep := false
	defer func() {
		_ = temp.Close()
		if !keep {
			_ = os.Remove(tempName)
		}
	}()
	if err := temp.Chmod(0o640); err != nil {
		return SaveOutput{}, fmt.Errorf("set temporary file mode: %w", err)
	}
	if _, err := temp.Write(markdown); err != nil {
		return SaveOutput{}, fmt.Errorf("write temporary file: %w", err)
	}
	if err := temp.Sync(); err != nil {
		return SaveOutput{}, fmt.Errorf("sync temporary file: %w", err)
	}
	if err := temp.Close(); err != nil {
		return SaveOutput{}, fmt.Errorf("close temporary file: %w", err)
	}
	if err := os.Rename(tempName, cleanTarget); err != nil {
		return SaveOutput{}, fmt.Errorf("commit output file: %w", err)
	}
	keep = true
	digest := fmt.Sprintf("%x", sha256.Sum256(markdown))
	sources := make([]Source, len(input.Sources))
	copy(sources, input.Sources)
	return SaveOutput{OK: true, Path: cleanTarget, Filename: input.Filename, Bytes: int64(len(markdown)), SHA256: digest, SavedAt: &now, Sources: sources}, nil
}

func buildMarkdown(input SaveInput, created time.Time) []byte {
	var text strings.Builder
	text.WriteString("# Сводка: ")
	text.WriteString(input.Query)
	text.WriteString("\n\n**Поисковый запрос:** ")
	text.WriteString(input.Query)
	text.WriteString("\n\n## Краткая сводка\n\n")
	text.WriteString(input.Content)
	text.WriteString("\n\n## Источники\n\n")
	if len(input.Sources) == 0 {
		text.WriteString("Источники не указаны.\n")
	} else {
		for _, source := range input.Sources {
			title := cleanSpace(source.Title)
			if title == "" {
				title = source.URL
			}
			text.WriteString("- [")
			text.WriteString(strings.ReplaceAll(title, "]", "\\]"))
			text.WriteString("](")
			text.WriteString(strings.TrimSpace(source.URL))
			text.WriteString(")\n")
		}
	}
	text.WriteString("\n---\nСоздано: ")
	text.WriteString(created.Format(time.RFC3339))
	text.WriteByte('\n')
	return []byte(text.String())
}

package pipeline

import (
	"crypto/sha256"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

func TestSaveAtomicSHAAndMarkdown(t *testing.T) {
	dir := t.TempDir()
	fixed := time.Date(2026, 9, 27, 12, 0, 0, 0, time.UTC)
	saver := NewSaver(dir)
	saver.Now = func() time.Time { return fixed }
	target := filepath.Join(dir, "summary.md")
	if err := os.WriteFile(target, []byte("old"), 0o600); err != nil {
		t.Fatal(err)
	}
	result, err := saver.Save(SaveInput{Filename: "summary.md", Query: "MCP", Content: "Exact summary.", Sources: []Source{{Title: "Article", URL: "https://en.wikipedia.org/wiki/MCP"}}})
	if err != nil {
		t.Fatal(err)
	}
	data, err := os.ReadFile(target)
	if err != nil {
		t.Fatal(err)
	}
	wantHash := fmt.Sprintf("%x", sha256.Sum256(data))
	if result.Path != target || result.SHA256 != wantHash || result.Bytes != int64(len(data)) {
		t.Fatalf("metadata mismatch: %+v", result)
	}
	text := string(data)
	for _, fragment := range []string{"# Сводка: MCP", "**Поисковый запрос:** MCP", "Exact summary.", "[Article](https://en.wikipedia.org/wiki/MCP)", fixed.Format(time.RFC3339)} {
		if !strings.Contains(text, fragment) {
			t.Errorf("missing %q", fragment)
		}
	}
	entries, _ := os.ReadDir(dir)
	if len(entries) != 1 || entries[0].Name() != "summary.md" {
		t.Fatalf("temporary files remain: %+v", entries)
	}
}

func TestSaveRejectsTraversalAndSize(t *testing.T) {
	saver := NewSaver(t.TempDir())
	for _, name := range []string{"../x.md", "/tmp/x.md", `a\\b.md`, "a/b.md", "not-text.txt", "..md"} {
		if _, err := saver.Save(SaveInput{Filename: name, Query: "q", Content: "x"}); err == nil {
			t.Fatalf("accepted %q", name)
		}
	}
	if _, err := saver.Save(SaveInput{Filename: "large.md", Query: "q", Content: strings.Repeat("x", MaxFileContent+1)}); err == nil {
		t.Fatal("accepted oversized content")
	}
}

package pipeline

import (
	"context"
	"encoding/json"
	"net/http"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

const (
	ServerName    = "day19-composition-mcp"
	ServerVersion = "1.0.0"
)

func NewServer(wikipedia *WikipediaClient, saver *Saver) *mcp.Server {
	server := mcp.NewServer(&mcp.Implementation{Name: ServerName, Version: ServerVersion}, &mcp.ServerOptions{
		Instructions: "Three independent tools form a model-orchestrated research pipeline: search, then summarize, then save_to_file. Do not skip or combine stages.",
	})
	registerTools(server, wikipedia, saver)
	return server
}

func registerTools(server *mcp.Server, wikipedia *WikipediaClient, saver *Saver) {
	openWorld, closedWorld, nonDestructive := true, false, false
	mcp.AddTool(server, &mcp.Tool{
		Name: SearchToolName, Title: "Search Wikipedia",
		Description: "Search the public Wikipedia API and return real introductory article text. This must be the first pipeline step. Pass its query and documents unchanged to summarize.",
		InputSchema: searchInputSchema(), OutputSchema: searchOutputSchema(),
		Annotations: &mcp.ToolAnnotations{ReadOnlyHint: true, IdempotentHint: true, OpenWorldHint: &openWorld},
	}, func(ctx context.Context, _ *mcp.CallToolRequest, input SearchInput) (*mcp.CallToolResult, SearchOutput, error) {
		result, err := wikipedia.Search(ctx, input)
		if err != nil {
			return toolFailure(), SearchOutput{OK: false, Documents: []Document{}, Error: failure(errorCode(err), err)}, nil
		}
		return nil, result, nil
	})

	mcp.AddTool(server, &mcp.Tool{
		Name: SummarizeToolName, Title: "Summarize search documents",
		Description: "Create a deterministic extractive summary only from the exact structured documents returned by search. This tool does not access the network.",
		InputSchema: summarizeInputSchema(), OutputSchema: summarizeOutputSchema(),
		Annotations: &mcp.ToolAnnotations{ReadOnlyHint: true, IdempotentHint: true, OpenWorldHint: &closedWorld},
	}, func(_ context.Context, _ *mcp.CallToolRequest, input SummarizeInput) (*mcp.CallToolResult, SummarizeOutput, error) {
		result, err := Summarize(input)
		if err != nil {
			return toolFailure(), SummarizeOutput{OK: false, Sources: []Source{}, Error: failure("invalid_argument", err)}, nil
		}
		return nil, result, nil
	})

	mcp.AddTool(server, &mcp.Tool{
		Name: SaveToolName, Title: "Save Markdown summary",
		Description: "Save the exact summary and sources returned by summarize as a Markdown file inside /data/outputs. This must be the final pipeline step.",
		InputSchema: saveInputSchema(), OutputSchema: saveOutputSchema(),
		Annotations: &mcp.ToolAnnotations{ReadOnlyHint: false, IdempotentHint: true, DestructiveHint: &nonDestructive, OpenWorldHint: &closedWorld},
	}, func(_ context.Context, _ *mcp.CallToolRequest, input SaveInput) (*mcp.CallToolResult, SaveOutput, error) {
		result, err := saver.Save(input)
		if err != nil {
			return toolFailure(), SaveOutput{OK: false, Sources: []Source{}, Error: failure(errorCode(err), err)}, nil
		}
		return nil, result, nil
	})
}

func Handler(wikipedia *WikipediaClient, saver *Saver) http.Handler {
	mux := http.NewServeMux()
	server := NewServer(wikipedia, saver)
	mux.Handle("/mcp", mcp.NewStreamableHTTPHandler(func(*http.Request) *mcp.Server { return server }, &mcp.StreamableHTTPOptions{
		Stateless: true, JSONResponse: true, MaxRequestBodyBytes: 1 << 20, PropagateRequestCancellation: true,
	}))
	mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, _ *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(map[string]string{"status": "ok", "service": ServerName})
	})
	return mux
}

func toolFailure() *mcp.CallToolResult { return &mcp.CallToolResult{IsError: true} }

func errorCode(err error) string {
	if err == nil {
		return "internal_error"
	}
	message := err.Error()
	if len(message) >= 9 && message[:9] == "Wikipedia" {
		return "upstream_error"
	}
	return "invalid_argument"
}

