package pipeline

import (
	"errors"
	"regexp"
	"sort"
	"strings"
	"unicode"
)

var sentenceBoundary = regexp.MustCompile(`[^.!?…]+(?:[.!?…]+|$)`)

type rankedSentence struct {
	text  string
	order int
	score int
}

func Summarize(input SummarizeInput) (SummarizeOutput, error) {
	input.Query = cleanSpace(input.Query)
	if input.Query == "" || len([]rune(input.Query)) > 300 {
		return SummarizeOutput{}, errors.New("query must contain 1 to 300 characters")
	}
	if input.MaxSentences < 1 || input.MaxSentences > 10 {
		return SummarizeOutput{}, errors.New("max_sentences must be between 1 and 10")
	}
	if len(input.Documents) > 5 {
		return SummarizeOutput{}, errors.New("documents must contain at most 5 items")
	}
	terms := meaningfulWords(input.Query)
	seen := map[string]bool{}
	all := make([]rankedSentence, 0)
	sources := make([]Source, 0, len(input.Documents))
	seenSources := map[string]bool{}
	order := 0
	for _, document := range input.Documents {
		document.Title, document.URL, document.Text = cleanSpace(document.Title), strings.TrimSpace(document.URL), cleanSpace(document.Text)
		if document.URL != "" && !seenSources[document.URL] {
			sources = append(sources, Source{Title: document.Title, URL: document.URL})
			seenSources[document.URL] = true
		}
		for _, match := range sentenceBoundary.FindAllString(document.Text, -1) {
			sentence := cleanSpace(match)
			key := strings.ToLower(strings.Trim(sentence, " .!?…"))
			if key == "" || seen[key] {
				continue
			}
			seen[key] = true
			words := meaningfulWords(sentence)
			score := len(words)
			for term := range terms {
				if words[term] {
					score += 12
				}
			}
			if len([]rune(sentence)) >= 45 && len([]rune(sentence)) <= 260 {
				score += 4
			}
			all = append(all, rankedSentence{text: sentence, order: order, score: score})
			order++
		}
	}
	warning := ""
	if len(all) == 0 {
		warning = "Недостаточно данных для составления сводки."
		return SummarizeOutput{OK: true, Query: input.Query, Sources: sources, InputDocuments: len(input.Documents), Warning: warning}, nil
	}
	ranked := append([]rankedSentence(nil), all...)
	sort.SliceStable(ranked, func(i, j int) bool {
		if ranked[i].score == ranked[j].score {
			return ranked[i].order < ranked[j].order
		}
		return ranked[i].score > ranked[j].score
	})
	count := input.MaxSentences
	if len(ranked) < count {
		count = len(ranked)
		warning = "Доступно меньше информативных предложений, чем запрошено."
	}
	chosen := append([]rankedSentence(nil), ranked[:count]...)
	sort.Slice(chosen, func(i, j int) bool { return chosen[i].order < chosen[j].order })
	parts := make([]string, len(chosen))
	for i := range chosen {
		parts[i] = chosen[i].text
	}
	return SummarizeOutput{OK: true, Query: input.Query, Summary: strings.Join(parts, " "), Sources: sources, InputDocuments: len(input.Documents), SentenceCount: len(chosen), Warning: warning}, nil
}

func meaningfulWords(value string) map[string]bool {
	words := map[string]bool{}
	var current []rune
	flush := func() {
		if len(current) >= 3 {
			words[string(current)] = true
		}
		current = current[:0]
	}
	for _, r := range strings.ToLower(value) {
		if unicode.IsLetter(r) || unicode.IsDigit(r) {
			current = append(current, r)
		} else {
			flush()
		}
	}
	flush()
	return words
}

package pipeline

import (
	"strings"
	"testing"
)

func TestSummarizeDeterministicExtractiveAndDeduplicated(t *testing.T) {
	input := SummarizeInput{Query: "Model Context Protocol", MaxSentences: 2, Documents: []Document{
		{Title: "A", URL: "https://en.wikipedia.org/wiki/A", Text: "Unrelated short sentence. Model Context Protocol connects AI applications to external systems. Repeated fact."},
		{Title: "B", URL: "https://en.wikipedia.org/wiki/B", Text: "Repeated fact. The protocol standardizes context exchange for language models."},
	}}
	first, err := Summarize(input)
	if err != nil {
		t.Fatal(err)
	}
	second, err := Summarize(input)
	if err != nil {
		t.Fatal(err)
	}
	if first.Summary != second.Summary {
		t.Fatalf("nondeterministic: %q vs %q", first.Summary, second.Summary)
	}
	if first.SentenceCount != 2 || first.InputDocuments != 2 || len(first.Sources) != 2 {
		t.Fatalf("wrong counts: %+v", first)
	}
	allText := input.Documents[0].Text + " " + input.Documents[1].Text
	for _, sentence := range sentenceBoundary.FindAllString(first.Summary, -1) {
		if !strings.Contains(allText, cleanSpace(sentence)) {
			t.Fatalf("invented sentence: %q", sentence)
		}
	}
	if strings.Count(first.Summary, "Repeated fact.") > 1 {
		t.Fatal("duplicate was not removed")
	}
}

func TestSummarizeEmptyAndDuplicateDocuments(t *testing.T) {
	empty, err := Summarize(SummarizeInput{Query: "topic", MaxSentences: 3, Documents: nil})
	if err != nil {
		t.Fatal(err)
	}
	if empty.Summary != "" || empty.Warning == "" || empty.SentenceCount != 0 {
		t.Fatalf("unexpected empty result: %+v", empty)
	}
	duplicate, err := Summarize(SummarizeInput{Query: "topic", MaxSentences: 3, Documents: []Document{{Title: "A", URL: "https://example/a", Text: "Same sentence."}, {Title: "A copy", URL: "https://example/a", Text: "Same sentence."}}})
	if err != nil {
		t.Fatal(err)
	}
	if duplicate.SentenceCount != 1 || len(duplicate.Sources) != 1 {
