func TestFilesEndpointListsAndReadsMarkdownOnly(t *testing.T) {
	dir := t.TempDir()
	if err := os.WriteFile(filepath.Join(dir, "summary.md"), []byte("# Safe\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(dir, "secret.txt"), []byte("hidden"), 0o600); err != nil {
		t.Fatal(err)
	}
	handler := Handler(nil, dir)
	list := httptest.NewRecorder()
	handler.ServeHTTP(list, httptest.NewRequest(http.MethodGet, "/api/files", nil))
	if list.Code != http.StatusOK || !strings.Contains(list.Body.String(), "summary.md") || strings.Contains(list.Body.String(), "secret.txt") {
		t.Fatalf("list response: %d %s", list.Code, list.Body.String())
	}
	read := httptest.NewRecorder()
	handler.ServeHTTP(read, httptest.NewRequest(http.MethodGet, "/api/files/summary.md", nil))
	if read.Code != http.StatusOK || !strings.Contains(read.Body.String(), "# Safe") {
		t.Fatalf("read response: %d %s", read.Code, read.Body.String())
	}
}

func TestSafeReadNameRejectsTraversal(t *testing.T) {
	for _, name := range []string{"../x.md", "/tmp/x.md", `a\\b.md`, "a/b.md", "..md", "x.txt", ""} {
		if safeReadName(name) {
			t.Fatalf("accepted %q", name)
		}
	}
	if !safeReadName("report-1.md") {
		t.Fatal("safe Markdown filename rejected")
	}
}

package web

import (
	"crypto/rand"
	"encoding/hex"
	"net/http"
	"sync"
	"time"

	"ai-challenge/day-19/internal/agent"
)

type conversation struct {
	mu       sync.Mutex
	messages []agent.Message
}

type conversationStore struct {
	mu       sync.Mutex
	sessions map[string]*conversation
}

func newConversationStore() *conversationStore {
	return &conversationStore{sessions: map[string]*conversation{}}
}

func (s *conversationStore) get(w http.ResponseWriter, r *http.Request) *conversation {
	id := ""
	if cookie, err := r.Cookie("day19_session"); err == nil {
		id = cookie.Value
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if existing := s.sessions[id]; id != "" && existing != nil {
		return existing
	}
	var raw [24]byte
	_, _ = rand.Read(raw[:])
	id = hex.EncodeToString(raw[:])
	created := &conversation{}
	s.sessions[id] = created
	http.SetCookie(w, &http.Cookie{Name: "day19_session", Value: id, Path: "/", HttpOnly: true, SameSite: http.SameSiteStrictMode, MaxAge: 86400})
	return created
}

func (s *conversationStore) reset(w http.ResponseWriter, r *http.Request) {
	if cookie, err := r.Cookie("day19_session"); err == nil {
		s.mu.Lock()
		delete(s.sessions, cookie.Value)
		s.mu.Unlock()
	}
	http.SetCookie(w, &http.Cookie{Name: "day19_session", Value: "", Path: "/", HttpOnly: true, SameSite: http.SameSiteStrictMode, MaxAge: -1, Expires: time.Unix(1, 0)})
}

func (c *conversation) history() []agent.Message { return append([]agent.Message(nil), c.messages...) }
func (c *conversation) appendTurn(messages []agent.Message) {
	c.messages = append(c.messages, messages...)
}

