package artifact

import (
	"crypto/sha256"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
	"time"

	"ai-challenge/day-20/internal/domain"
)

const MaxMarkdown = 512 << 10

var safeFilename = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9._-]{0,119}\.md$`)

type Store struct {
	OutputDir string
	Now       func() time.Time
}

func NewStore(dir string) *Store { return &Store{OutputDir: dir, Now: time.Now} }

func Build(input domain.ReportInput) (domain.ReportOutput, error) {
	input.Topic = strings.TrimSpace(input.Topic)
	input.Title = strings.TrimSpace(input.Title)
	if input.Topic == "" || input.Title == "" {
		return domain.ReportOutput{}, errors.New("topic and title are required")
	}
	var b strings.Builder
	fmt.Fprintf(&b, "# %s\n\n## Тема\n\n%s\n\n## Сводка Wikipedia\n\n%s\n\n## Репозиторий GitHub\n\n", input.Title, input.Topic, input.Knowledge.Summary)
	fmt.Fprintf(&b, "- **Репозиторий:** [%s](%s)\n- **Описание:** %s\n- **Язык:** %s\n- **Ветка:** `%s`\n- **Stars / forks / issues:** %d / %d / %d\n- **Обновлён:** %s\n\n", input.Repository.FullName, input.Repository.URL, input.Repository.Description, input.Repository.Language, input.Repository.DefaultBranch, input.Repository.Stars, input.Repository.Forks, input.Repository.OpenIssues, input.Repository.UpdatedAt)
	b.WriteString("## Последний релиз\n\n")
	if input.LatestRelease.Found {
		fmt.Fprintf(&b, "[%s — %s](%s), опубликован %s. Draft: %t. Prerelease: %t.\n\n", input.LatestRelease.Tag, input.LatestRelease.Name, input.LatestRelease.URL, input.LatestRelease.PublishedAt, input.LatestRelease.Draft, input.LatestRelease.Prerelease)
	} else {
		b.WriteString("Опубликованные релизы не найдены.\n\n")
	}
	b.WriteString("## Источники\n\n")
	sources := append([]domain.Source(nil), input.KnowledgeSources...)
	if input.Repository.URL != "" {
		sources = append(sources, domain.Source{Title: input.Repository.FullName, URL: input.Repository.URL})
	}
	if input.LatestRelease.Found && input.LatestRelease.URL != "" {
		sources = append(sources, domain.Source{Title: input.LatestRelease.Tag, URL: input.LatestRelease.URL})
	}
	for _, s := range sources {
		fmt.Fprintf(&b, "- [%s](%s)\n", strings.ReplaceAll(strings.TrimSpace(s.Title), "]", "\\]"), strings.TrimSpace(s.URL))
	}
	markdown := b.String()
	sum := fmt.Sprintf("%x", sha256.Sum256([]byte(markdown)))
	return domain.ReportOutput{OK: true, Markdown: markdown, Sources: sources, SHA256: sum, Sections: []string{"Тема", "Сводка Wikipedia", "Репозиторий GitHub", "Последний релиз", "Источники"}}, nil
}
func validName(name string) bool {
	return !filepath.IsAbs(name) && !strings.Contains(name, "..") && !strings.ContainsAny(name, `/\`) && safeFilename.MatchString(name)
}
func (s *Store) resolve(name string) (string, error) {
	name = strings.TrimSpace(name)
	if !validName(name) {
		return "", errors.New("filename must be a safe relative .md filename")
	}
	root, err := filepath.Abs(s.OutputDir)
	if err != nil {
		return "", err
	}
	target := filepath.Join(root, name)
	if filepath.Dir(target) != root {
		return "", errors.New("resolved path is outside output directory")
	}
	return target, nil
}
func (s *Store) Save(input domain.SaveInput) (domain.SaveOutput, error) {
	target, err := s.resolve(input.Filename)
	if err != nil {
		return domain.SaveOutput{}, err
	}
	if input.Markdown == "" {
		return domain.SaveOutput{}, errors.New("markdown cannot be empty")
	}
	data := []byte(input.Markdown)
	if len(data) > MaxMarkdown {
		return domain.SaveOutput{}, fmt.Errorf("markdown exceeds %d bytes", MaxMarkdown)
	}
	if err = os.MkdirAll(filepath.Dir(target), 0750); err != nil {
		return domain.SaveOutput{}, err
	}
	tmp, err := os.CreateTemp(filepath.Dir(target), ".day20-*.tmp")
	if err != nil {
		return domain.SaveOutput{}, err
	}
	tmpName := tmp.Name()
	committed := false
	defer func() {
		_ = tmp.Close()
		if !committed {
			_ = os.Remove(tmpName)
		}
	}()
	if err = tmp.Chmod(0640); err == nil {
		_, err = tmp.Write(data)
	}
	if err == nil {
		err = tmp.Sync()
	}
	if err == nil {
		err = tmp.Close()
	}
	if err == nil {
		err = os.Rename(tmpName, target)
	}
	if err != nil {
		return domain.SaveOutput{}, fmt.Errorf("atomic write: %w", err)
	}
	committed = true
	now := s.Now().UTC()
	sum := fmt.Sprintf("%x", sha256.Sum256(data))
	return domain.SaveOutput{OK: true, Path: target, Filename: input.Filename, Bytes: int64(len(data)), SHA256: sum, SavedAt: &now, Sources: append([]domain.Source(nil), input.Sources...)}, nil
}
func (s *Store) List() (domain.ListOutput, error) {
	entries, err := os.ReadDir(s.OutputDir)
	if errors.Is(err, os.ErrNotExist) {
		return domain.ListOutput{OK: true, Files: []domain.FileInfo{}}, nil
	}
	if err != nil {
		return domain.ListOutput{}, err
	}
	files := []domain.FileInfo{}
	for _, e := range entries {
		if e.IsDir() || !validName(e.Name()) {
			continue
		}
		out, err := s.Read(domain.ReadInput{Filename: e.Name()})
		if err != nil {
			continue
		}
		info, _ := e.Info()
		files = append(files, domain.FileInfo{Name: e.Name(), Path: out.Path, Bytes: out.Bytes, ModifiedAt: info.ModTime().UTC(), SHA256: out.SHA256})
	}
	sort.Slice(files, func(i, j int) bool { return files[i].Name < files[j].Name })
	return domain.ListOutput{OK: true, Files: files, Count: len(files)}, nil
}
func (s *Store) Read(input domain.ReadInput) (domain.ReadOutput, error) {
	target, err := s.resolve(input.Filename)
	if err != nil {
		return domain.ReadOutput{}, err
	}
	f, err := os.Open(target)
	if err != nil {
		return domain.ReadOutput{}, err
	}
	defer f.Close()
	data, err := io.ReadAll(io.LimitReader(f, MaxMarkdown+1))
	if err != nil {
		return domain.ReadOutput{}, err
	}
	if len(data) > MaxMarkdown {
		return domain.ReadOutput{}, errors.New("file exceeds size limit")
	}
	sum := fmt.Sprintf("%x", sha256.Sum256(data))
	return domain.ReadOutput{OK: true, Filename: input.Filename, Path: target, Markdown: string(data), Bytes: int64(len(data)), SHA256: sum}, nil
}

package artifact

import (
	"ai-challenge/day-20/internal/domain"
	"crypto/sha256"
	"fmt"
	"os"
	"testing"
)

func TestBuildSaveReadListAndSafety(t *testing.T) {
	in := domain.ReportInput{Topic: "MCP", Title: "Report", Knowledge: domain.SummarizeOutput{OK: true, Summary: "Exact summary", Sources: []domain.Source{{Title: "Wiki", URL: "https://example.com"}}}, KnowledgeSources: []domain.Source{{Title: "Wiki", URL: "https://example.com"}}, Repository: domain.RepositoryOutput{OK: true, FullName: "o/r", URL: "https://github.com/o/r", Stars: 1}, LatestRelease: domain.ReleaseOutput{OK: true, Found: false}}
	a, _ := Build(in)
	b, _ := Build(in)
	if a.Markdown != b.Markdown || a.SHA256 != b.SHA256 {
		t.Fatal("report not deterministic")
	}
	s := NewStore(t.TempDir())
	saved, err := s.Save(domain.SaveInput{Filename: "report.md", Markdown: a.Markdown, Sources: a.Sources})
	if err != nil || saved.SHA256 != a.SHA256 {
		t.Fatalf("%+v %v", saved, err)
	}
	data, _ := os.ReadFile(saved.Path)
	if saved.SHA256 != fmt.Sprintf("%x", sha256.Sum256(data)) {
		t.Fatal("hash mismatch")
	}
	read, _ := s.Read(domain.ReadInput{Filename: "report.md"})
	list, _ := s.List()
	if read.Markdown != a.Markdown || list.Count != 1 {
		t.Fatalf("read/list mismatch")
	}
	for _, name := range []string{"../x.md", "/tmp/x.md", `a\\b.md`} {
		if _, err := s.Save(domain.SaveInput{Filename: name, Markdown: "x"}); err == nil {
			t.Fatalf("unsafe accepted: %s", name)
		}
	}
}

package githubapi

import (
	"ai-challenge/day-20/internal/domain"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"strings"
	"time"
)

const maxBody = 2 << 20

type Client struct {
	HTTPClient     *http.Client
	BaseURL, Token string
	Now            func() time.Time
}

func NewClient(client *http.Client, token string) *Client {
	if client == nil {
		client = &http.Client{Timeout: 12 * time.Second}
	}
	return &Client{HTTPClient: client, BaseURL: "https://api.github.com", Token: strings.TrimSpace(token), Now: time.Now}
}
func validate(in domain.RepositoryInput) (domain.RepositoryInput, error) {
	in.Owner = strings.TrimSpace(in.Owner)
	in.Repository = strings.TrimSpace(in.Repository)
	if in.Owner == "" || in.Repository == "" || len(in.Owner) > 100 || len(in.Repository) > 100 || strings.ContainsAny(in.Owner+in.Repository, "/\\") {
		return in, errors.New("owner and repository must be simple non-empty names")
	}
	return in, nil
}
func (c *Client) get(ctx context.Context, path string, target any) (int, error) {
	base, err := url.Parse(strings.TrimRight(c.BaseURL, "/"))
	if err != nil {
		return 0, err
	}
	base.Path += path
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, base.String(), nil)
	if err != nil {
		return 0, err
	}
	req.Header.Set("Accept", "application/vnd.github+json")
	req.Header.Set("User-Agent", "day20-orchestration-mcp/1.0")
	if c.Token != "" {
		req.Header.Set("Authorization", "Bearer "+c.Token)
	}
	resp, err := c.HTTPClient.Do(req)
	if err != nil {
		return 0, fmt.Errorf("GitHub request: %w", err)
	}
	defer resp.Body.Close()
	body, err := io.ReadAll(io.LimitReader(resp.Body, maxBody+1))
	if err != nil {
		return resp.StatusCode, err
	}
	if len(body) > maxBody {
		return resp.StatusCode, errors.New("GitHub response exceeds size limit")
	}
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return resp.StatusCode, fmt.Errorf("GitHub returned HTTP %d", resp.StatusCode)
	}
	if err = json.Unmarshal(body, target); err != nil {
		return resp.StatusCode, fmt.Errorf("decode GitHub response: %w", err)
	}
	return resp.StatusCode, nil
}
func (c *Client) Repository(ctx context.Context, in domain.RepositoryInput) (domain.RepositoryOutput, error) {
	in, err := validate(in)
	if err != nil {
		return domain.RepositoryOutput{}, err
	}
	var raw struct {
		FullName        string `json:"full_name"`
		HTMLURL         string `json:"html_url"`
		Description     string `json:"description"`
		Language        string `json:"language"`
		DefaultBranch   string `json:"default_branch"`
		UpdatedAt       string `json:"updated_at"`
		StargazersCount int    `json:"stargazers_count"`
		ForksCount      int    `json:"forks_count"`
		OpenIssuesCount int    `json:"open_issues_count"`
	}
	_, err = c.get(ctx, "/repos/"+url.PathEscape(in.Owner)+"/"+url.PathEscape(in.Repository), &raw)
	if err != nil {
		return domain.RepositoryOutput{}, err
	}
	now := c.Now().UTC()
	return domain.RepositoryOutput{OK: true, Owner: in.Owner, Repository: in.Repository, FullName: raw.FullName, URL: raw.HTMLURL, Description: raw.Description, Language: raw.Language, DefaultBranch: raw.DefaultBranch, Stars: raw.StargazersCount, Forks: raw.ForksCount, OpenIssues: raw.OpenIssuesCount, UpdatedAt: raw.UpdatedAt, Source: "GitHub REST API", FetchedAt: &now}, nil
}
func (c *Client) LatestRelease(ctx context.Context, in domain.RepositoryInput) (domain.ReleaseOutput, error) {
	in, err := validate(in)
	if err != nil {
		return domain.ReleaseOutput{}, err
	}
	var raw struct {
		Tag        string `json:"tag_name"`
		Name       string `json:"name"`
		URL        string `json:"html_url"`
		Published  string `json:"published_at"`
		Draft      bool   `json:"draft"`
		Prerelease bool   `json:"prerelease"`
	}
	status, err := c.get(ctx, "/repos/"+url.PathEscape(in.Owner)+"/"+url.PathEscape(in.Repository)+"/releases/latest", &raw)
	now := c.Now().UTC()
	if status == http.StatusNotFound {
		return domain.ReleaseOutput{OK: true, Owner: in.Owner, Repository: in.Repository, Found: false, Source: "GitHub REST API", FetchedAt: &now}, nil
	}
	if err != nil {
		return domain.ReleaseOutput{}, err
	}
	return domain.ReleaseOutput{OK: true, Owner: in.Owner, Repository: in.Repository, Found: true, Tag: raw.Tag, Name: raw.Name, URL: raw.URL, PublishedAt: raw.Published, Draft: raw.Draft, Prerelease: raw.Prerelease, Source: "GitHub REST API", FetchedAt: &now}, nil
}

