				w.WriteHeader(tc.status)
				_, _ = w.Write([]byte(tc.body))
			}))
			defer s.Close()
			c := NewClient(s.Client())
			c.BaseURL = s.URL
			if _, err := c.Search(context.Background(), domain.SearchInput{Query: "x", Limit: 1}); err == nil {
				t.Fatal("expected error")
			}
		})
